exercise.solution:
poeni = int(input("Broj poena (0-100): "))

if poeni >= 90:
    print("Odličan (5)")
elif poeni >= 75:
    print("Vrlo dobar (4)")
elif poeni >= 60:
    print("Dobar (3)")
elif poeni >= 50:
    print("Dovoljan (2)")
else:
    print("Nedovoljan (1)")

